INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Auskunft
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Haben Betroffene gemäß Art. 15 DSGVO das Recht, Auskunft über die Verarbeitung ihrer personenbezogenen Daten zu verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 15 DSGVO gewährt das Recht auf Auskunft"}, {"text": "Nein", "correct": false, "because": "Auskunftsrecht ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen die Auskunft gemäß Art. 15 DSGVO ohne Angabe von Gründen verweigern?', 2, '[{"text": "Nein", "correct": true, "because": "Verweigerung nur bei begründeten Ausnahmen möglich"}, {"text": "Ja", "correct": false, "because": "Gründe müssen angegeben werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Auskunft nach Art. 15 DSGVO immer schriftlich erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Elektronische oder andere Formen sind zulässig"}, {"text": "Ja", "correct": false, "because": "Flexibilität in der Form"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene eine Kopie ihrer Daten im Rahmen des Auskunftsrechts verlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 15 Abs. 3 DSGVO erlaubt eine Datenkopie"}, {"text": "Nein", "correct": false, "because": "Kopie ist Teil des Rechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Auskunft gemäß Art. 15 DSGVO kostenpflichtig für Betroffene?', 2, '[{"text": "Nein", "correct": true, "because": "Grundsätzlich kostenfrei, außer bei unverhältnismäßigem Aufwand"}, {"text": "Ja", "correct": false, "because": "Kostenfreiheit ist Standard"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was umfasst das Recht auf Auskunft gemäß Art. 15 DSGVO primär?', 2, '[{"text": "Information über verarbeitete Daten", "correct": true, "because": "Betroffene erfahren, welche Daten verarbeitet werden"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenlöschung", "correct": false, "because": "Anderes Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information müssen Unternehmen gemäß Art. 15 DSGVO auf Anfrage bereitstellen?', 3, '[{"text": "Zweck der Verarbeitung", "correct": true, "because": "Pflichtangabe nach Art. 15 Abs. 1a"}, {"text": "Serverstandort", "correct": false, "because": "Nicht zwingend"}, {"text": "Softwareversion", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um auf eine Auskunftsanfrage zu reagieren?', 2, '[{"text": "1 Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO legt dies fest"}, {"text": "1 Woche", "correct": false, "because": "Zu kurz"}, {"text": "3 Monate", "correct": false, "because": "Zu lang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist bei der Umsetzung des Rechts auf Auskunft am wichtigsten?', 2, '[{"text": "Daten leicht zugänglich machen", "correct": true, "because": "Erleichtert Auskunftserteilung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schutz, nicht Auskunft"}, {"text": "Daten löschen", "correct": false, "because": "Anderes Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Nichtbeachtung des Rechts auf Auskunft?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Indirekt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen Betroffenen gemäß Art. 15 DSGVO auf Anfrage bereitgestellt werden?', 4, '[{"text": "Zweck der Verarbeitung", "correct": true, "because": "Pflicht nach Art. 15 Abs. 1a"}, {"text": "Kategorien der Daten", "correct": true, "because": "Pflicht nach Art. 15 Abs. 1b"}, {"text": "Empfänger der Daten", "correct": true, "because": "Pflicht nach Art. 15 Abs. 1c"}, {"text": "Softwareentwicklungszeit", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Umsetzung des Rechts auf Auskunft?', 3, '[{"text": "Datenstruktur übersichtlich halten", "correct": true, "because": "Erleichtert Zugriff"}, {"text": "Prozesse zur Anfragenbearbeitung", "correct": true, "because": "Sichert Frist"}, {"text": "Datenkopie bereitstellen", "correct": true, "because": "Pflicht nach Art. 15 Abs. 3"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Schutz, nicht Auskunft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Gründe können eine Verweigerung des Rechts auf Auskunft rechtfertigen?', 4, '[{"text": "Schutz der Rechte anderer", "correct": true, "because": "Art. 15 Abs. 4 erlaubt Einschränkung"}, {"text": "Unverhältnismäßiger Aufwand", "correct": true, "because": "Kosten dürfen angemessen sein"}, {"text": "Öffentliche Sicherheit", "correct": true, "because": "Ausnahme bei Gefährdung"}, {"text": "Unternehmensinteresse", "correct": false, "because": "Kein allgemeiner Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Auskunft haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Schadensersatz", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei der Softwareplanung für das Recht auf Auskunft zu berücksichtigen?', 3, '[{"text": "Daten leicht abrufbar machen", "correct": true, "because": "Erleichtert Auskunft"}, {"text": "Automatisierte Antwortsysteme", "correct": true, "because": "Effiziente Bearbeitung"}, {"text": "Dokumentation der Verarbeitung", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht Speicherbegrenzung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Auskunft umfasst den Verarbeitungszweck. b) Es ist für Betroffene kostenpflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweck ja, kostenfrei nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betroffene können eine Datenkopie verlangen. b) Die Auskunft muss immer schriftlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kopie ja, Form flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unternehmen müssen innerhalb eines Monats auf Auskunftsanfragen reagieren. b) Verweigerung ist ohne Grund möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Frist ja, Gründe nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verstöße gegen das Recht auf Auskunft können Bußgelder nach sich ziehen. b) Die Datenkopie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Kopie Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Auskunft schützt die Transparenz für Betroffene. b) Unternehmen müssen Daten ohne Anfrage bereitstellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transparenz ja, Anfrage nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

